"""Create three intentionally different static composition studies.
These are local art compositions, not screenshots of working game UI.
"""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'design/diagon-alley/compositions'
ART='/src/arcana/presentation/content-packs/diagon-alley/art/'
OUT.mkdir(parents=True,exist_ok=True)
def img(file, cls='', style=''):
    return f'<img src="{ART+file}" class="{cls}" style="{style}" alt="">'
CSS='''*{box-sizing:border-box}html,body{margin:0;width:1440px;height:900px;overflow:hidden}body{background:#120f22;color:#f9e8bb;font-family:Georgia,serif}main{position:relative;isolation:isolate;width:100%;height:100%;overflow:hidden}main:after{content:"";position:absolute;inset:0;box-shadow:inset 0 0 120px 35px #0d091dc9;pointer-events:none;z-index:9}.backdrop{position:absolute;width:100%;height:100%;object-fit:cover;z-index:-2}.veil{position:absolute;inset:0;background:linear-gradient(180deg,#100d2466,transparent 25%,transparent 70%,#110e23e8);z-index:-1}.title{position:absolute;left:48px;top:28px;letter-spacing:.09em;font-size:30px;font-weight:400;margin:0;text-shadow:0 3px 8px #000}.subtitle{display:block;font-size:13px;letter-spacing:.32em;margin-top:9px;color:#d4bb8a}.hud{position:absolute;right:150px;top:34px;display:flex;gap:20px;font-size:26px}.hud span{background:#1a1527dc;border:1px solid #ad8654;border-radius:100px;padding:10px 22px}.settings{position:absolute;width:72px;height:72px;right:42px;top:23px;filter:drop-shadow(0 5px 5px #000a)}.objects{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);display:flex;align-items:end;gap:24px}.object{display:grid;justify-items:center;color:#fce9b6;font-size:19px;text-shadow:0 3px 5px #000;min-width:136px;transform:rotate(-4deg)}.object:nth-child(even){transform:rotate(4deg)}.object img{width:128px;height:128px;object-fit:contain;filter:drop-shadow(0 10px 9px #000c)}.route{position:absolute;left:100px;top:145px;width:1050px;height:545px}.node{position:absolute;width:88px;height:88px;filter:drop-shadow(0 0 18px #ffcb79a0)}.road{position:absolute;inset:0;overflow:visible}.road path{fill:none;stroke:#f2ce83;stroke-width:4;stroke-dasharray:4 11;stroke-linecap:round;filter:drop-shadow(0 0 3px #fff3bf)}.party{position:absolute;right:42px;bottom:165px;display:flex;flex-direction:column;gap:12px}.party .portrait{width:72px;height:85px;object-fit:cover;border-radius:45% 45% 30% 30%;border:3px solid #d4af6a;box-shadow:0 6px 20px #000c}.label{position:absolute;left:65px;bottom:192px;font-size:15px;letter-spacing:.17em;text-transform:uppercase}.stamp{font:13px system-ui;position:absolute;right:28px;bottom:10px;opacity:.65}.atlas-board{position:absolute;width:1030px;height:620px;left:185px;top:123px;transform:rotate(-4deg);background:linear-gradient(135deg,#eee2b7,#c4a575 80%);clip-path:polygon(2% 2%,98% 0,100% 97%,1% 100%);box-shadow:0 15px 35px #0008}.atlas-board:before{content:"";position:absolute;inset:20px;border:2px solid #8f6d43}.atlas-streets{position:absolute;inset:0;width:100%;height:100%;opacity:.6}.atlas-streets path{fill:none;stroke:#92754f;stroke-width:40}.atlas-streets .thin{stroke-width:4;stroke-dasharray:4 6}.counter{position:absolute;bottom:0;height:250px;width:100%;background:linear-gradient(#5f3b22ee,#21111de8);box-shadow:0 -8px 25px #000a;border-top:4px solid #bc9259}.hero-box{position:absolute;width:570px;height:570px;left:435px;top:250px;filter:drop-shadow(0 0 35px #e3b46088)}.halo{position:absolute;width:850px;height:850px;left:295px;top:40px}.hero-title{position:absolute;top:145px;left:0;width:100%;text-align:center;font-size:44px;letter-spacing:.04em}.floating-beans{position:absolute;left:120px;top:330px;width:230px;filter:drop-shadow(0 20px 15px #000b)}.floating-album{position:absolute;right:110px;top:325px;width:245px;transform:rotate(8deg);filter:drop-shadow(0 20px 15px #000b)}.coin{display:inline-block;width:21px;height:21px;border-radius:50%;background:radial-gradient(circle at 30% 20%,#ffeda7,#c28c36 60%,#714014);box-shadow:0 0 0 2px #f6ce7a;vertical-align:0}.energy{color:#a9e3e4}.route .node img{width:100%;height:100%}'''
def common():
    return '<h1 class="title">DIAGON ALLEY<span class="subtitle">CALLEJÓN DIAGÓN</span></h1><div class="hud"><span><i class="coin"></i> 150</span><span class="energy">✦ 45</span></div>'+img('props/settings.svg','settings')
def dock():
    return '<div class="objects">'+''.join('<div class="object">'+img(file)+f'<span>{name}</span></div>' for file,name in [('props/map.svg','Explorar'),('props/album.svg','Colección'),('props/sweetshop.svg','Dulcería'),('props/letter.svg','Encargos')])+'</div>'
nodes=[(15,55,'pact'),(175,315,'chest'),(335,118,'duel'),(500,330,'refuge'),(675,150,'encounter'),(850,275,'boss')]
def route():
    return '<div class="route"><svg class="road" viewBox="0 0 1050 545"><path d="M58 98C104 180 148 264 218 358S322 241 378 161 483 290 543 373 661 265 718 193 831 240 893 318"/></svg>'+''.join('<div class="node" style="left:'+str(x)+'px;top:'+str(y)+'px"><img src="/src/arcana/presentation/content-packs/arcana/art/icons/node-'+kind+'.svg" alt=""></div>' for x,y,kind in nodes)+'</div>'
def output(name, content):
    (OUT/(name+'.html')).write_text('<!doctype html><html lang="es"><meta charset="utf-8"><title>'+name+'</title><style>'+CSS+'</style><main>'+content+'<span class="stamp">ESTUDIO LOCAL · COMPOSICIÓN, NO UI FUNCIONAL</span></main></html>')
output('01-callejon-de-maravillas', img('scene/diagon-alley.webp','backdrop')+'<div class="veil"></div>'+common()+route()+dock()+'<span class="label">EL CALLEJÓN · 3 / 6</span>')
output('02-atlas-del-merodeador',img('scene/sweetshop.webp','backdrop')+'<div class="veil"></div>'+common()+'''<div class="atlas-board"><svg class="atlas-streets" viewBox="0 0 1030 620"><path d="M0 100 300 160 330 480 700 390 1050 450M220 0 280 140 730 70 790 400 650 620"/><path class="thin" d="M0 100 300 160 330 480 700 390 1050 450M220 0 280 140 730 70 790 400 650 620"/></svg>'''+route()+'</div>'+dock())
output('03-maravilla-del-dulcero',img('scene/sweetshop.webp','backdrop')+'<div class="veil"></div><div class="counter"></div>'+common()+img('fx/halo.svg','halo')+'<div class="hero-title">Una nueva historia te espera</div>'+img('frog/closed.webp','hero-box')+img('props/beans-jar.webp','floating-beans')+img('props/album.svg','floating-album')+dock())
(OUT/'comparison.json').write_text(json.dumps({'selected':'01-callejon-de-maravillas','selectionAuthority':'User delegates visual direction and full implementation on 15 October2026. No new approval gate.', 'alternatives':[{'id':'01-callejon-de-maravillas','composition':'Full scene; route and object navigation float in the world.','strength':'Exploration dominates; warm Harry Potter alley context.','risk':'Path legibility requires restrained vignette and node halos.'},{'id':'02-atlas-del-merodeador','composition':'Paper atlas over the counter, with small buildings and route.','strength':'Strong tactile map metaphor and route contrast.','risk':'Paper can become another rectangular app panel; scene less immersive.'},{'id':'03-maravilla-del-dulcero','composition':'Large central product and collector props on a stage.','strength':'Best for magical surprise and opening ritual.','risk':'Store-first composition obscures exploration; use only inside commerce.'}]},ensure_ascii=False,indent=2)+'\n')
print('DIAGON_COMPOSITIONS 3 local HTML studies')
